<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {useRouter} from 'vue-router';import TokenModal from '../components/TokenModal.vue';import {adminApi} from '../services/api';import type{ClientInput}from'../types';const props=defineProps<{id?:string}>();const router=useRouter();const form=reactive<ClientInput>({displayName:'',slug:'',zoneId:'',zoneName:'',recordId:'',recordName:'',recordType:'A'});const error=ref('');const token=ref('');onMounted(async()=>{if(props.id)Object.assign(form,await adminApi.client(props.id));});async function submit(){error.value='';try{if(props.id){await adminApi.update(props.id,form);await router.push(`/clients/${props.id}`);}else{const result=await adminApi.create(form);token.value=result.token;}}catch(e){error.value=e instanceof Error?e.message:'儲存失敗';}}function close(){token.value='';void router.push('/clients');}</script>
<template><h1 class="mb-6 text-2xl font-bold">{{props.id?'編輯':'新增'}} Client</h1><form class="card grid max-w-3xl gap-4 sm:grid-cols-2" @submit.prevent="submit"><label><span class="label">顯示名稱</span><input v-model="form.displayName" class="input" required maxlength="100"></label><label><span class="label">Slug</span><input v-model="form.slug" class="input" required pattern="[a-z0-9][a-z0-9-]{1,62}"></label><label><span class="label">Zone ID</span><input v-model="form.zoneId" class="input" required></label><label><span class="label">Zone Name</span><input v-model="form.zoneName" class="input" required></label><label><span class="label">Record ID</span><input v-model="form.recordId" class="input" required></label><label><span class="label">Record Name</span><input v-model="form.recordName" class="input" required></label><label><span class="label">Record Type</span><select v-model="form.recordType" class="input"><option>A</option><option>AAAA</option></select></label><p v-if="error" class="text-red-300 sm:col-span-2">{{error}}</p><div class="flex gap-2 sm:col-span-2"><button class="btn-primary">儲存並驗證 Record</button><RouterLink class="btn-secondary" to="/clients">取消</RouterLink></div></form><TokenModal v-if="token" :token="token" :slug="form.slug" :hostname="form.recordName" @close="close"/></template>
